from django.contrib.sitemaps import Sitemap
from .models import ClinicalPatientCase

class PatientCaseStudySitemap(Sitemap):
    changefreq = 'monthly'
    priority = 0.5

    def items(self):
        # Strictly publish only fully anonymized cases approved for public research distribution
        return ClinicalPatientCase.objects.filter(is_anonymized=True, is_published_publicly=True)

    def location(self, item):
        return f"/clinical/cases/{item.uuid}/"
